def brute(n,edges,x):
    # exhaustive shortest paths via Bellman relaxation on independently built state graph
    e=[]
    for u,v in edges:
      e += [(u,v,1),(n+v,n+u,1)]
    for v in range(n):e.append((v,n+v,x));e.append((n+v,v,x))
    d=[10**9]*(2*n);d[0]=0
    for _ in range(2*n-1):
      change=False
      for u,v,w in e:
        if d[u]+w<d[v]:d[v]=d[u]+w;change=True
      if not change:break
