class Solution:
    def numberOfWays(self, n: int, x: int, y: int) -> int:
        MOD = 10**9 + 7
        dp = [0] * (min(n, x) + 1)
        dp[0] = 1
        for i in range(1, n + 1):
            ndp = [0] * len(dp)
            hi = min(i, x)
            for k in range(1, hi + 1):
                ndp[k] = (dp[k] * k + dp[k - 1] * (x - k + 1) * y) % MOD
            dp = ndp
        return sum(dp) % MOD

