class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        n = len(s)

        # steps[x] is the number of popcount operations needed for x to reach 1.
        steps = [0] * (n + 1)
        for x in range(2, n + 1):
            steps[x] = 1 + steps[x.bit_count()]
        valid = [steps[j] <= k - 1 for j in range(n + 1)]

        # Binomial coefficients modulo MOD.
        combinations = [[0] * (n + 1) for _ in range(n + 1)]
        combinations[0][0] = 1
        for a in range(1, n + 1):
            combinations[a][0] = combinations[a][a] = 1
            for b in range(1, a):
                combinations[a][b] = (combinations[a - 1][b - 1] + combinations[a - 1][b]) % MOD

        # Count values strictly below s, grouped by their total number of set bits.
        answer = 0
        prefix_ones = 0
        for i, bit in enumerate(s):
            if bit == '1':
                remaining_positions = n - i - 1
                for total_ones in range(1, n + 1):
                    needed = total_ones - prefix_ones
                    if valid[total_ones] and 0 <= needed <= remaining_positions:
                        answer += combinations[remaining_positions][needed]
                prefix_ones += 1

        return answer % MOD

