class Solution:
    def largestPalindrome(self, n: int, k: int) -> str:
        m = (n + 1) // 2
        coeff = []
        for i in range(m):
            if n - 1 - i == i:
                coeff.append(pow(10, i, k))
            else:
                coeff.append((pow(10, i, k) + pow(10, n - 1 - i, k)) % k)
        # Bit r in each mask means residue r can be obtained.
        suffix = [0] * (m + 1)
        suffix[m] = 1  # residue zero
        for i in range(m - 1, -1, -1):
            nxt = suffix[i + 1]
            mask = 0
            for d in range(10):
                shift = (d * coeff[i]) % k
                for r in range(k):
                    if (nxt >> r) & 1:
                        mask |= 1 << ((r + shift) % k)
            suffix[i] = mask
        digits = []
        rem = 0
        for i, c in enumerate(coeff):
            for d in range(9 if i == 0 else 9, 0 if i == 0 else -1, -1):
                need = (-rem - d * c) % k
                if (suffix[i + 1] >> need) & 1:
                    digits.append(str(d))
                    rem = (rem + d * c) % k
                    break
        left = ''.join(digits)
        return left + (left[:-1][::-1] if n % 2 else left[::-1])

