class Solution:
    def countNonDecreasingSubarrays(self, nums: List[int], k: int) -> int:
        n=len(nums); pref=[0]*(n+1)
        for i,x in enumerate(nums): pref[i+1]=pref[i]+x
        nxt=[n]*n; st=[]
        for i in range(n-1,-1,-1):
            while st and nums[st[-1]]<=nums[i]: st.pop()
            nxt[i]=st[-1] if st else n; st.append(i)
        L=n.bit_length(); jump=[nxt]
        costs=[[nums[i]*(nxt[i]-i)-(pref[nxt[i]]-pref[i]) for i in range(n)]]
        for b in range(1,L):
            prev=jump[-1]; pc=costs[-1]; j=[n]*n; c=[0]*n
            for i in range(n):
                m=prev[i]
                if m<n: j[i]=prev[m]; c[i]=pc[i]+pc[m]
                else: c[i]=pc[i]
            jump.append(j); costs.append(c)
        ans=0
        for start in range(n):
            p=start; used=0
            for b in range(L-1,-1,-1):
                q=jump[b][p]
                if q<n and used+costs[b][p]<=k:
                    used+=costs[b][p]; p=q
            q=nxt[p]; lo=1; hi=q-p
            while lo<hi:
                mid=(lo+hi+1)//2
                c=nums[p]*mid-(pref[p+mid]-pref[p])
                if c<=k-used: lo=mid
                else: hi=mid-1
            ans+=(p-start)+lo
        return ans

