        g = [[] for _ in range(n)]
        for u, v, w in edges:
            g[u].append((v, w))
            g[v].append((u, w))

        parent = [-2] * n
        parent[0] = -1
        order = [0]
        for u in order:
            for v, w in g[u]:
                if v != parent[u]:
                    parent[v] = u
                    order.append(v)

