        dp1 = [0] * n
        for u in reversed(order):
            base = 0
            gains = []
            for v, w in g[u]:
                if parent[v] == u:
                    base += dp0[v]
                    gains.append(w + dp1[v] - dp0[v])
            gains.sort(reverse=True)
            positives = [x for x in gains if x > 0]
