from bisect import bisect_left

class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        a, rest = p.split('*', 1)
        b, c = rest.split('*', 1)
        n = len(s)

        def occurrences(x):
            if not x:
                return list(range(n + 1))
            m = len(x)
            pi = [0] * m
            j = 0
            for i in range(1, m):
                while j and x[i] != x[j]:
                    j = pi[j - 1]
                if x[i] == x[j]:
                    j += 1
                pi[i] = j
            out = []
            j = 0
            for i, ch in enumerate(s):
                while j and ch != x[j]:
                    j = pi[j - 1]
                if ch == x[j]:
                    j += 1
                if j == m:
                    out.append(i - m + 1)
                    j = pi[j - 1]
            return out

        aa, bb, cc = map(occurrences, (a, b, c))
        ans = n + 1
        for start in aa:
            ib = bisect_left(bb, start + len(a))
            if ib == len(bb):
                continue
            bs = bb[ib]
            ic = bisect_left(cc, bs + len(b))
            if ic == len(cc):
                continue
            end = cc[ic] + len(c)
            ans = min(ans, end - start)
        return -1 if ans == n + 1 else ans

