from typing import List

class Solution:
    def findAnswer(self, parent: List[int], s: str) -> List[bool]:
        n = len(parent)
        children = [[] for _ in range(n)]
        for v in range(1, n):
            children[parent[v]].append(v)

        # Iterative postorder DFS, preserving increasing child order.
        order = []
        stack = [(0, False)]
        while stack:
            x, done = stack.pop()
            if done:
                order.append(x)
            else:
                stack.append((x, True))
                for y in reversed(children[x]):
                    stack.append((y, False))

        pos = [0] * n
        size = [1] * n
        post = []
        for i, x in enumerate(order):
            pos[x] = i
            post.append(s[x])
            # Children precede x in postorder, so their sizes are ready.
            for y in children[x]:
                size[x] += size[y]

        text = ''.join(post)

        # Manacher radii: odd[i] counts the center character; even[i]
        # is the radius around the gap immediately before i.
        odd = [0] * n
        left, right = 0, -1
        for i in range(n):
            k = 1 if i > right else min(odd[left + right - i], right - i + 1)
            while i - k >= 0 and i + k < n and text[i - k] == text[i + k]:
                k += 1
            odd[i] = k
            if i + k - 1 > right:
                left, right = i - k + 1, i + k - 1

        even = [0] * n
        left, right = 0, -1
        for i in range(n):
            k = 0 if i > right else min(even[left + right - i + 1], right - i + 1)
            while i - k - 1 >= 0 and i + k < n and text[i - k - 1] == text[i + k]:
                k += 1
            even[i] = k
            if i + k - 1 > right:
                left, right = i - k, i + k - 1

        answer = [False] * n
        for x in range(n):
            end = pos[x] + 1
            length = size[x]
            start = end - length
            if length % 2:
                center = (start + end - 1) // 2
                answer[x] = odd[center] >= length // 2 + 1
            else:
                center = (start + end) // 2
                answer[x] = even[center] >= length // 2
        return answer

