import random

def fast(n, ps):
    s=set()
    for a,b in ps:
        s.add((a,b))
        for da,db in ((2,1),(1,2),(-1,2),(-2,1),(-2,-1),(-1,-2),(1,-2),(2,-1)):
            x,y=a+da,b+db
            if 1<=x<=n and 1<=y<=n:s.add((x,y))
    return n*n-len(s)

def slow(n, ps):
    occupied=set(ps)
    ans=0
    for i in range(1,n+1):
        for j in range(1,n+1):
            if (i,j) in occupied: continue
            if all(not (abs(i-a),abs(j-b)) in ((1,2),(2,1)) for a,b in ps): ans+=1
    return ans
for n in range(1,9):
    cells=[(i,j) for i in range(1,n+1) for j in range(1,n+1)]
    for _ in range(100):
        ps=random.sample(cells,random.randrange(len(cells)+1))
        assert fast(n,ps)==slow(n,ps),(n,ps,fast(n,ps),slow(n,ps))
print('random exhaustive cross-check passed')

