        n = len(energyDrinkA)
        dpA = [0] * n
        dpB = [0] * n
        dpA[0] = energyDrinkA[0]
        dpB[0] = energyDrinkB[0]
        for i in range(1, n):
            dpA[i] = energyDrinkA[i] + dpA[i - 1]
            dpB[i] = energyDrinkB[i] + dpB[i - 1]
            if i >= 2:
                dpA[i] = max(dpA[i], energyDrinkA[i] + dpB[i - 2])
                dpB[i] = max(dpB[i], energyDrinkB[i] + dpA[i - 2])
        return max(dpA[-1], dpB[-1])

