        mins = [None] * k
        mins[0] = 0
        pref = 0
        ans = None
        for j, x in enumerate(nums, 1):
            pref += x
            r = j % k
            if mins[r] is not None:
                val = pref - mins[r]
                if ans is None or val > ans:
                    ans = val
            if mins[r] is None or pref < mins[r]:
                mins[r] = pref
        return ans

